<script lang="ts">import { dateTime } from '$lib/format';let {data}=$props();const labels:Record<string,string>={'appointment.created':'Cita creada','appointment.cancelled':'Cita cancelada','appointment.completed':'Cita atendida','doctor.created':'Médico añadido','slot.created':'Horario publicado','shift.created':'Jornada creada','shift.updated':'Jornada modificada','shift.deleted':'Jornada eliminada','role.doctor':'Rol: médico','role.reception':'Rol: recepción','role.patient':'Rol: paciente','role.admin':'Rol: administrador'};</script>
<svelte:head><title>Auditoría · CitaCloud</title></svelte:head>
